from pathlib import Path
from lxml import etree

base = Path('/root/pptx_unpacked')
slides_dir = base / 'ppt' / 'slides'
rels_dir = slides_dir / '_rels'

ns = {
    'p':'http://schemas.openxmlformats.org/presentationml/2006/main',
    'a':'http://schemas.openxmlformats.org/drawingml/2006/main',
}
A_NS = ns['a']
P_NS = ns['p']

EMU = 914400
slide_w = 12192000
slide_h = 6858000
box_w = 10972800  # 12.0 in
box_h = 365760    # 0.4 in
box_left = 609600 # centered
box_top = 6217920 # 6.8 in from top


def get_text(sp):
    texts = sp.xpath('.//a:t', namespaces=ns)
    return ''.join([t.text or '' for t in texts]).strip()


def is_placeholder(sp):
    return sp.xpath('./p:nvSpPr/p:nvPr/p:ph', namespaces=ns)


def ensure_child(parent, tag):
    child = parent.find(tag, ns)
    if child is None:
        child = etree.Element(f'{{{A_NS}}}{tag.split(":")[1]}')
        parent.append(child)
    return child


def set_run_format(r):
    rPr = r.find('a:rPr', ns)
    if rPr is None:
        rPr = etree.Element(f'{{{A_NS}}}rPr')
        r.insert(0, rPr)
    rPr.set('sz', '1600')
    rPr.set('b', '0')
    rPr.set('dirty', '0')
    # color
    solid = rPr.find('a:solidFill', ns)
    if solid is None:
        solid = etree.Element(f'{{{A_NS}}}solidFill')
        rPr.insert(0, solid)
    for child in list(solid):
        solid.remove(child)
    srgb = etree.Element(f'{{{A_NS}}}srgbClr')
    srgb.set('val', '989596')
    solid.append(srgb)
    # fonts
    latin = rPr.find('a:latin', ns)
    if latin is None:
        latin = etree.Element(f'{{{A_NS}}}latin')
        rPr.append(latin)
    latin.set('typeface', 'Arial')
    ea = rPr.find('a:ea', ns)
    if ea is None:
        ea = etree.Element(f'{{{A_NS}}}ea')
        rPr.append(ea)
    ea.set('typeface', 'Arial')
    cs = rPr.find('a:cs', ns)
    if cs is None:
        cs = etree.Element(f'{{{A_NS}}}cs')
        rPr.append(cs)
    cs.set('typeface', 'Arial')


def set_endpara_format(p):
    end = p.find('a:endParaRPr', ns)
    if end is None:
        end = etree.Element(f'{{{A_NS}}}endParaRPr')
        p.append(end)
    end.set('sz', '1600')
    end.set('b', '0')
    end.set('dirty', '0')
    solid = end.find('a:solidFill', ns)
    if solid is None:
        solid = etree.Element(f'{{{A_NS}}}solidFill')
        end.insert(0, solid)
    for child in list(solid):
        solid.remove(child)
    srgb = etree.Element(f'{{{A_NS}}}srgbClr')
    srgb.set('val', '989596')
    solid.append(srgb)
    latin = end.find('a:latin', ns)
    if latin is None:
        latin = etree.Element(f'{{{A_NS}}}latin')
        end.append(latin)
    latin.set('typeface', 'Arial')
    ea = end.find('a:ea', ns)
    if ea is None:
        ea = etree.Element(f'{{{A_NS}}}ea')
        end.append(ea)
    ea.set('typeface', 'Arial')
    cs = end.find('a:cs', ns)
    if cs is None:
        cs = etree.Element(f'{{{A_NS}}}cs')
        end.append(cs)
    cs.set('typeface', 'Arial')


def center_paragraphs(txBody):
    for p in txBody.xpath('./a:p', namespaces=ns):
        pPr = p.find('a:pPr', ns)
        if pPr is None:
            pPr = etree.Element(f'{{{A_NS}}}pPr')
            p.insert(0, pPr)
        pPr.set('algn', 'ctr')


def update_shape(sp):
    # position
    spPr = sp.find('p:spPr', ns)
    if spPr is None:
        spPr = etree.Element(f'{{{P_NS}}}spPr')
        # insert after nvSpPr
        nv = sp.find('p:nvSpPr', ns)
        if nv is not None:
            sp.insert(sp.index(nv)+1, spPr)
        else:
            sp.insert(0, spPr)
    xfrm = spPr.find('a:xfrm', ns)
    if xfrm is None:
        xfrm = etree.Element(f'{{{A_NS}}}xfrm')
        spPr.insert(0, xfrm)
    off = xfrm.find('a:off', ns)
    if off is None:
        off = etree.Element(f'{{{A_NS}}}off')
        xfrm.insert(0, off)
    ext = xfrm.find('a:ext', ns)
    if ext is None:
        ext = etree.Element(f'{{{A_NS}}}ext')
        xfrm.insert(1, ext)
    off.set('x', str(box_left))
    off.set('y', str(box_top))
    ext.set('cx', str(box_w))
    ext.set('cy', str(box_h))

    txBody = sp.find('p:txBody', ns)
    if txBody is None:
        return
    center_paragraphs(txBody)
    # format runs
    for r in txBody.xpath('.//a:r', namespaces=ns):
        set_run_format(r)
    # format endPara
    for p in txBody.xpath('./a:p', namespaces=ns):
        set_endpara_format(p)


# Collect paper titles in order
paper_titles = []
seen = set()
for slide in sorted(slides_dir.glob('slide*.xml')):
    tree = etree.parse(str(slide))
    for sp in tree.xpath('//p:sp', namespaces=ns):
        if is_placeholder(sp):
            continue
        text = get_text(sp)
        if text and text not in seen:
            paper_titles.append(text)
            seen.add(text)

# Update existing slides
for slide in sorted(slides_dir.glob('slide*.xml')):
    tree = etree.parse(str(slide))
    changed = False
    for sp in tree.xpath('//p:sp', namespaces=ns):
        text = get_text(sp)
        if text in seen and not is_placeholder(sp):
            update_shape(sp)
            changed = True
    if changed:
        tree.write(str(slide), encoding='ascii', xml_declaration=True)

# Create new slide 7 from slide6
slide7 = slides_dir / 'slide7.xml'
slide7_rels = rels_dir / 'slide7.xml.rels'
if not slide7.exists():
    (slides_dir / 'slide6.xml').replace(slide7)  # move
    (rels_dir / 'slide6.xml.rels').replace(slide7_rels)
    # copy back original slide6
    from shutil import copyfile
    copyfile(slide7, slides_dir / 'slide6.xml')
    copyfile(slide7_rels, rels_dir / 'slide6.xml.rels')

# Modify slide7 content
s7 = etree.parse(str(slide7))
root = s7.getroot()
# Update title text
for sp in root.xpath('//p:sp', namespaces=ns):
    text = get_text(sp)
    # title placeholder
    if sp.xpath('./p:nvSpPr/p:nvPr/p:ph[@type="title"]', namespaces=ns):
        for t in sp.xpath('.//a:t', namespaces=ns):
            t.text = 'Reference'
        # keep existing formatting
# Remove non-placeholder paper title textbox
for sp in root.xpath('//p:sp', namespaces=ns):
    if is_placeholder(sp):
        continue
    text = get_text(sp)
    if text in seen:
        sp.getparent().remove(sp)
        break

# Update body placeholder with numbered bullets
body_sp = None
for sp in root.xpath('//p:sp', namespaces=ns):
    if sp.xpath('./p:nvSpPr/p:nvPr/p:ph[@idx="1"]', namespaces=ns):
        body_sp = sp
        break
if body_sp is not None:
    txBody = body_sp.find('p:txBody', ns)
    if txBody is not None:
        # clear existing paragraphs
        for p in list(txBody.xpath('./a:p', namespaces=ns)):
            txBody.remove(p)
        for i, title in enumerate(paper_titles, start=1):
            p = etree.Element(f'{{{A_NS}}}p')
            pPr = etree.Element(f'{{{A_NS}}}pPr')
            bu = etree.Element(f'{{{A_NS}}}buAutoNum')
            bu.set('type', 'arabicPeriod')
            if i == 1:
                bu.set('startAt', '1')
            pPr.append(bu)
            p.append(pPr)
            r = etree.Element(f'{{{A_NS}}}r')
            rPr = etree.Element(f'{{{A_NS}}}rPr')
            rPr.set('lang', 'en-US')
            rPr.set('dirty', '0')
            r.append(rPr)
            t = etree.Element(f'{{{A_NS}}}t')
            t.text = title
            r.append(t)
            p.append(r)
            end = etree.Element(f'{{{A_NS}}}endParaRPr')
            end.set('lang', 'en-US')
            end.set('dirty', '0')
            p.append(end)
            txBody.append(p)

s7.write(str(slide7), encoding='ascii', xml_declaration=True)

